-- Approved catalog-only inspection. No application rows, secrets, function bodies or trigger arguments.
BEGIN READ ONLY;
SET LOCAL statement_timeout = '15s';
SELECT jsonb_build_object(
 'server_version',current_setting('server_version'),
 'schemas',(SELECT coalesce(jsonb_agg(nspname ORDER BY nspname),'[]') FROM pg_namespace WHERE nspname NOT LIKE 'pg_%' AND nspname<>'information_schema'),
 'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'estimated_rows',c.reltuples) ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','rudo') AND c.relkind IN ('r','p','v','m')),
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default_expression',CASE WHEN d.adbin IS NULL THEN NULL WHEN pg_get_expr(d.adbin,d.adrelid) ~ '^(now\(\)|CURRENT_TIMESTAMP|CURRENT_DATE|true|false|NULL|[-0-9.]+|gen_random_uuid\(\)|uuid_generate_v4\(\)|nextval\(''.*''::regclass\)|''(pending|active|user|bot|english|unregistered|\{\}|\[\])''::(text|jsonb|json|character varying))$' THEN pg_get_expr(d.adbin,d.adrelid) ELSE '[WITHHELD: non-allowlisted default; restricted review required]' END) ORDER BY n.nspname,c.relname,a.attnum),'[]') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname IN ('public','rudo') AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid)) ORDER BY n.nspname,c.relname,k.conname),'[]') FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','rudo')),
 'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY schemaname,tablename,indexname),'[]') FROM pg_indexes i WHERE schemaname IN ('public','rudo')),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies p WHERE schemaname IN ('public','rudo')),
 'grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'grantee',grantee,'privilege',privilege_type) ORDER BY table_schema,table_name,grantee,privilege_type),'[]') FROM information_schema.role_table_grants WHERE table_schema IN ('public','rudo')),
 'schema_grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type)),'[]') FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a WHERE n.nspname IN ('public','rudo')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'type_bits',t.tgtype,'function_schema',pn.nspname,'function_name',p.proname,'argument_count',t.tgnargs,'internal',t.tgisinternal)),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE n.nspname IN ('public','rudo')),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl)),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','rudo')),
 'runtime_roles',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'superuser',rolsuper,'bypass_rls',rolbypassrls)),'[]') FROM pg_roles WHERE rolname IN ('rudo_api','rudo_worker')),
 'migration_history_table',to_regclass('supabase_migrations.schema_migrations'),
 'migration_history_columns',(SELECT coalesce(jsonb_agg(column_name ORDER BY ordinal_position),'[]') FROM information_schema.columns WHERE table_schema='supabase_migrations' AND table_name='schema_migrations')
) AS inventory;
ROLLBACK;
